function encodeWholesaleCost(value,map){return String(Math.round(Number(value)||0)).replace(/\\d/g,d=>map[d]??map[Number(d)]??d);}
function printLabel(){const manual={name:document.querySelector('#label-name')?.value||'',brand:document.querySelector('#label-brand')?.value||'',reference:document.querySelector('#label-reference')?.value||'',selling_price:document.querySelector('#label-price')?.value||'',company_price:document.querySelector('#label-cost')?.value||'',barcode_id:document.querySelector('#label-code')?.value||''};const queue=state.labelQueue.length?state.labelQueue:[manual];if(!queue.length||(!state.labelQueue.length&&(!manual.name||!manual.selling_price)))throw new Error('Ajoutez des articles à la file ou saisissez un nom et un prix.');const copies=Math.max(1,Math.min(999,Number(document.querySelector('#label-copies')?.value)||1)),w=Math.max(15,Number(document.querySelector('#label-width')?.value)||30),h=Math.max(15,Number(document.querySelector('#label-height')?.value)||45),f={name:document.querySelector('#label-show-name')?.checked!==false,price:document.querySelector('#label-show-price')?.checked!==false,barcode:document.querySelector('#label-show-barcode')?.checked!==false,brand:document.querySelector('#label-show-brand')?.checked===true,reference:document.querySelector('#label-show-reference')?.checked===true,cost:document.querySelector('#label-show-cost')?.checked===true,logo:document.querySelector('#label-show-logo')?.checked!==false};const labels=queue.flatMap(item=>Array.from({length:copies},()=>'<div class="label">'+(f.logo?'<img class="logo" src="'+location.origin+'/assets/samarinapos-mark.svg">':'')+(f.name?'<div class="name">'+esc(item.name||'')+'</div>':'')+(f.brand?'<div>'+esc(item.brand||'')+'</div>':'')+(f.reference?'<div>'+esc(item.model_reference||item.reference||'')+'</div>':'')+(f.price?'<div class="price">'+esc(item.selling_price||item.sell_price||'')+' DZD</div>':'')+(f.cost?'<div class="cost">COST '+esc(encodeWholesaleCost(item.company_price||item.purchase_cost_dzd,state.labelCipherMap||{}))+'</div>':'')+(f.barcode?'<div class="code">'+esc(item.barcode_id||item.itemid||'')+'</div>':'')+'</div>')).join('');const win=window.open('','_blank','width=500,height=700');if(!win)throw new Error('Autorisez la fenêtre d’impression.');win.document.write('<!doctype html><html><head><title>SamarinaPOS · Étiquettes</title><style>@page{size:'+w+'mm '+h+'mm;margin:1mm}body{font-family:Arial;margin:0}.label{height:'+(h-2)+'mm;display:flex;flex-direction:column;align-items:center;justify-content:center;page-break-after:always;border:1px solid #ddd}.logo{width:34px;height:20px;object-fit:contain}.name{font-size:11pt;font-weight:bold}.price{font-size:18pt;font-weight:bold;color:#2563eb}.code{font-size:9pt;letter-spacing:1px}.cost{font-size:8pt;color:#555}</style></head><body>'+labels+'<script>window.onload=()=>window.print()</script></body></html>');win.document.close();}
root.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el)return;try{if(el.dataset.priceTier){const item=basket().items.find(x=>String(x._id)===String(state.selectedLineId));const tier=Number(el.dataset.priceTier),price=item&&Number(item['selling_price'+(tier===1?'':'_'+tier)]??(tier===1?item.selling_price:0));if(item&&price>0){item.price_tier=tier;item.selling_price=price;state.drawer=null;render();}return;}if(el.dataset.action==='apply-custom-price'){const item=basket().items.find(x=>String(x._id)===String(state.selectedLineId));const price=Number(document.querySelector('#custom-line-price')?.value);if(!item||!Number.isFinite(price)||price<=0)throw new Error('Prix personnalisé invalide.');item.selling_price=price;item.price_tier=0;state.drawer=null;render();return;}if(el.dataset.paymentFill){if(el.dataset.paymentFill==='credit'&&!basket().customer){toast('Le crédit est réservé aux clients enregistrés.','error');return;}const form=document.querySelector('#checkout-form');if(form){for(const key of ['cash','tpe','baridimob','credit'])form.elements[key].value='0';if(form.elements[el.dataset.paymentFill])form.elements[el.dataset.paymentFill].value=String(total());const remainder=document.querySelector('#payment-remainder');if(remainder)remainder.textContent='0,00 DZD';}return;}if(el.dataset.caisseTab){state.caisseTab=el.dataset.caisseTab;state.caisseFilter='';if(state.caisseTab==='recent')state.caisseRecent=undefined;render();return;}if(el.dataset.caisseFilter){state.caisseFilter=el.dataset.caisseFilter;state.caisseTab='articles';render();return;}if(el.dataset.action==='clear-basket'){basket().items=[];basket().discount=0;render();return;}if(el.dataset.action==='quick-add'){if(searchResults[0])addItem(searchResults[0]);return;}if(el.dataset.action==='sale-note'){state.drawer={title:'Note de vente',html:'<form id="sale-note-form" class="form-grid"><div class="form-field full"><label>Note</label><textarea class="field" name="note" rows="3"></textarea></div><div class="form-field full"><button class="btn primary">Enregistrer</button></div></form>'};render();return;}if(el.dataset.action==='apply-coupon'){toast('Aucun moteur de coupon n’est configuré pour cette boutique.','error');return;}if(el.dataset.view){state.view=el.dataset.view;state.tab=el.dataset.tab!==undefined?Number(el.dataset.tab):0;state.query='';state.drawer=null;location.hash=state.view;await render();return;}if(el.dataset.tab!==undefined){state.tab=Number(el.dataset.tab);await render();return;}if(el.dataset.closeBasket){if(state.baskets.length>1){const id=Number(el.dataset.closeBasket);state.baskets=state.baskets.filter(x=>Number(x.id)!==id);if(Number(state.activeBasket)===id)state.activeBasket=state.baskets[0].id;render();}return;}if(el.dataset.basket){state.activeBasket=Number(el.dataset.basket);render();return;}if(el.dataset.addItem){const item=searchResults.find(x=>String(x._id)===el.dataset.addItem);if(item)addItem(item);return;}if(el.dataset.qty){const item=basket().items.find(x=>String(x._id)===el.dataset.id);if(item){const next=item.quantity+Number(el.dataset.qty),available=Number(item.available_quantity);if(Number(el.dataset.qty)>0&&item.track_inventory&&!item.negative_stock&&Number.isFinite(available)&&next>available){toast('Stock insuffisant.','error');return;}item.quantity=Math.max(1,next);render();}return;}if(el.dataset.remove){basket().items=basket().items.filter(x=>String(x._id)!==el.dataset.remove);render();return;}if(el.dataset.customer){const item=(state.customerResults||[]).find(x=>String(x._id)===el.dataset.customer);if(item)basket().customer={_id:item._id,name:item.name||item.customer_name,phone:item.phone||item.customer_phone||item.mobile||'',debt:item.balance||item.outstanding||0};state.drawer=null;render();return;}if(el.dataset.loadReturnSale){const sale=await get('sales/'+encodeURIComponent(document.querySelector('[name=sale_id]')?.value||''));state.returnSale=sale;state.drawer={title:'Retour ticket · '+esc(sale.sales_id||sale.sale_number||sale._id),html:returnSaleForm(sale)};render();return;}if(el.dataset.remind){await post('credit/reminder/'+encodeURIComponent(el.dataset.remind),{});toast('Relance WhatsApp envoyée.','success');return;}if(el.dataset.whatsappSale){await post('whatsapp/send-receipt',{sale_id:el.dataset.whatsappSale,phone_number:el.dataset.phone||''});toast('Ticket envoyé sur WhatsApp.','success');return;}if(el.dataset.printSale){const sale=await get('sales/'+el.dataset.printSale);if(!window.electronAPI?.printer?.printReceipt)throw new Error('Impression ESC/POS disponible uniquement sur le poste POSNIC.');await window.electronAPI.printer.printReceipt(sale,{});toast('Ticket envoyé à l’imprimante.','success');return;}if(el.dataset.zrStatus){await patch('delivery-zr/'+encodeURIComponent(el.dataset.zrStatus)+'/status',{status:'LIVRE'});toast('Statut ZR Express mis à jour.','success');render();return;}if(el.dataset.settle){state.drawer={title:'Encaisser un versement',html:`<form id="settle-form" data-customer-id="${esc(el.dataset.settle)}" class="form-grid"><div class="form-field"><label>Montant DZD</label><input class="field" name="amount" type="number" min=".01" step=".01" required></div><div class="form-field"><label>Mode</label><select class="field" name="method"><option>Cash</option><option>BaridiMob</option><option>TPE</option></select></div><div class="form-field full"><button class="btn primary">Enregistrer le versement</button></div></form>`};render();return;}if(el.dataset.revoke){await post('handsets/'+encodeURIComponent(el.dataset.revoke)+'/revoke',{});toast('Appareil révoqué.','success');render();return;}if(el.dataset.zrCancel){await post('delivery-zr/'+encodeURIComponent(el.dataset.zrCancel)+'/cancel',{});toast('Demande d’annulation envoyée.','success');render();return;}if(el.dataset.queueLabel){const item=state.records.find(x=>String(x._id)===el.dataset.queueLabel);if(item){state.labelQueue.push(item);toast('Article ajouté à la file d’étiquettes.','success');}return;}if(el.dataset.editItem){const item=await get('items/'+el.dataset.editItem);state.drawer={title:'Modifier un article',html:`<form id="item-form" data-id="${esc(item._id)}" class="form-grid compact-edit"><div class="form-field full"><label>Nom</label><input class="field" name="name" value="${esc(item.name)}" required></div><div class="form-field"><label>Catégorie</label><input class="field" name="category_name" value="${esc(item.category_name||'')}"></div><div class="form-field"><label>Marque</label><input class="field" name="brand" value="${esc(item.brand||'')}"></div><div class="form-field"><label>Prix d’achat DZD</label><input class="field" name="company_price" type="number" min="0" step=".01" value="${Number(item.company_price||item.purchase_cost_dzd)||0}"></div><div class="form-field"><label>Prix de vente 1</label><input class="field" name="selling_price" type="number" min="0" step=".01" value="${Number(item.selling_price)||0}"></div><div class="form-field"><label>Prix de vente 2</label><input class="field" name="selling_price_2" type="number" min="0" step=".01" value="${Number(item.selling_price_2)||0}"></div><div class="form-field"><label>Prix de vente 3</label><input class="field" name="selling_price_3" type="number" min="0" step=".01" value="${Number(item.selling_price_3)||0}"></div><div class="form-field"><label>Stock actuel</label><input class="field" name="available_quantity" type="number" min="0" step=".001" value="${Number(item.available_quantity)||0}"></div><div class="form-field full"><label>Image (URL)</label><input class="field" name="image_url" value="${esc(item.image_url||item.image||'')}"></div><div class="form-field full"><button class="btn primary">Enregistrer l’article</button></div></form>`};render();return;}await handleAction(el.dataset.action,el);}catch(err){toast(err.message,'error');}});
