root.addEventListener('input',e=>{if(e.target.closest('#zakat-form')){const n=id=>Math.max(0,Number(document.querySelector('#'+id)?.value)||0),nissab=n('zakat-gold-price')*85,net=Math.max(0,n('zakat-cash')+n('zakat-stock')+n('zakat-receivables')-n('zakat-liabilities')),eligible=document.querySelector('#zakat-hawl')?.checked===true&&nissab>0&&net>=nissab;document.querySelector('#zakat-nissab').textContent=money(nissab)+' DZD';document.querySelector('#zakat-net').textContent=money(net)+' DZD';document.querySelector('#zakat-due').textContent=money(eligible?net*.025:0)+' DZD';}if(e.target.id==='label-name'||e.target.id==='label-price'||e.target.id==='label-code'){const n=document.querySelector('#label-preview-name'),p=document.querySelector('#label-preview-price'),c=document.querySelector('#label-preview-code');if(n)n.textContent=document.querySelector('#label-name')?.value||'Nom de l’article';if(p)p.textContent=(document.querySelector('#label-price')?.value||'0.00')+' DZD';if(c)c.textContent=document.querySelector('#label-code')?.value||'Code-barres';}if(e.target.closest('#receipt-design-form')){const f=e.target.form,preview=document.querySelector('#receipt-preview');if(preview){preview.querySelector('b').textContent=f.elements.headerLine1.value||'SamarinaPOS';const divs=preview.querySelectorAll('.receipt-center div');if(divs[0])divs[0].textContent=f.elements.headerLine2.value||'';const foot=preview.querySelectorAll('div');const footer=[...foot].filter(x=>x.textContent.includes('Merci pour votre visite')||x.dataset.footer==='2');if(footer[0])footer[0].textContent=f.elements.footerLine1.value||'';}}if(e.target.form?.id==='new-item-form'&&['name','brand_abbreviation','reference_date','model_reference'].includes(e.target.name)){const f=e.target.form,generated=[f.elements.name.value,f.elements.brand_abbreviation.value,f.elements.reference_date.value,f.elements.model_reference.value].map(x=>String(x||'').trim()).filter(Boolean).join(' ').toLowerCase(),out=f.querySelector('#new-item-generated-name');if(out)out.textContent=generated||'—';}});
root.addEventListener('click',async e=>{const month=e.target.closest('[data-calendar-month]');if(month){const current=state.calendarMonth?new Date(state.calendarMonth+'-01T12:00:00'):new Date();current.setMonth(current.getMonth()+Number(month.dataset.calendarMonth));state.calendarMonth=current.getFullYear()+'-'+String(current.getMonth()+1).padStart(2,'0');await render();return;}const day=e.target.closest('[data-calendar-day]');if(day){const date=day.dataset.calendarDay,rows=rowsOf(await get('sales',{starting_date:date,ending_date:date,limit:100,page:1}));state.drawer={title:'Ventes du '+date,html:table(rows,[{label:'Ticket',keys:['sales_id','sale_number']},{label:'Client',keys:['customer_name']},{label:'Total DZD',render:r=>money(r.sales_total)+' DZD'},{label:'Action',render:r=>'<button class="btn" data-print-sale="'+esc(r._id)+'">Réimprimer</button>'}])};render();}});
