root.addEventListener('submit',async e=>{const form=e.target;if(!form.matches('form'))return;e.preventDefault();const fd=new FormData(form);try{if(form.id==='login-form'){await post('auth/login',{username:fd.get('username'),password:fd.get('password')});state.user=await get('auth/me');toast('Connexion réussie.','success');render();}else if(form.id==='return-lookup'){const id=String(fd.get('sale_id')||'').trim();const sale=await get('sales/'+encodeURIComponent(id));state.returnSale=sale;state.drawer={title:'Retour ticket · '+(sale.sales_id||sale.sale_number||sale._id),html:returnSaleForm(sale)};render();}else if(form.id==='return-form'){const sale=state.returnSale;if(!sale)throw new Error('Aucun ticket chargé.');const returnItems=(sale.items||[]).map((line,index)=>{const qty=Math.max(0,Number(document.querySelector('[name=return_qty_'+index+']')?.value)||0);if(!qty)return null;const originalQty=Math.max(1,Number(line.item_quantity)||1),lineTotal=Number(line.total_amount)||originalQty*(Number(line.item_price)||0);return {item_id:line.item_id||line.item||line.id,item_name:line.item_name||line.name,item_quantity:qty,item_price:Number(line.item_price)||0,total_amount:Math.round((lineTotal/originalQty)*qty*100)/100,item_unit:line.item_unit||'qty',tax:line.tax,tax_type:line.tax_type,igst_tax:line.igst_tax,cgst_tax:line.cgst_tax,sgst_tax:line.sgst_tax};}).filter(Boolean);if(!returnItems.length)throw new Error('Indiquez au moins une quantité à retourner.');const result=await post('sales/returnSales',{sales_id:sale._id||sale.sales_id,items:sale.items||[],items_return:returnItems,refund_method:fd.get('refund_method'),reason:fd.get('reason'),partial_check:String(sale.partial_check||'false'),payment_pending:Number(sale.payment_pending)||0,extra_discount:0,extra_discount_type:'price'});state.drawer=null;state.returnSale=null;toast('Retour enregistré · '+money(result?.return_amount||returnItems.reduce((n,x)=>n+x.total_amount,0))+' DZD','success');render();}else if(form.id==='checkout-form'){await checkout(form);}else if(form.id==='quantity-form'){const item=basket().items.find(x=>String(x._id)===String(form.dataset.lineId));const quantity=Number(fd.get('quantity')),available=Number(item?.available_quantity);if(!item||!Number.isFinite(quantity)||quantity<1)throw new Error('Quantité invalide.');if(item.track_inventory&&!item.negative_stock&&Number.isFinite(available)&&quantity>available)throw new Error('Stock insuffisant.');item.quantity=quantity;state.drawer=null;render();}else if(form.id==='sale-note-form'){basket().note=String(fd.get('note')||'').trim();state.drawer=null;toast('Note de vente enregistrée.','success');render();}else if(form.id==='close-form'){const body=Object.fromEntries(fd.entries());const counted_cash=[2000,1000,500,200,100].reduce((sum,value)=>sum+value*(Number(body['denom_'+value])||0),0);const result=await post('sales/cashierDayClose',{date:body.date,counted_cash});if(localStorage.getItem('samarinapos-auto-z-report')==='true'){const phone=localStorage.getItem('samarinapos-owner-whatsapp')||'';if(phone){const summary=await get('sales/cashierDaySummary',{starting_date:body.date,ending_date:body.date,type:'VIEW'});await post('whatsapp/sendMessage',{phone_number:phone,message:'Z-Report SamarinaPOS · '+body.date+'\n'+JSON.stringify(summary)});}}toast('Clôture enregistrée. Écart : '+money(result?.difference)+' DZD','success');render();}else if(form.id==='quick-expense-form'){const amount=Number(fd.get('amount')),reason=String(fd.get('reason')||'').trim();if(!Number.isFinite(amount)||amount<=0||!reason)throw new Error('Saisissez un montant et une raison valides.');await post('expenses/quick',{amount,reason});state.drawer=null;toast('Dépense enregistrée dans le journal officiel.','success');render();}else if(form.id==='quick-advance-form'){const amount=Number(fd.get('amount')),workerId=String(fd.get('worker_id')||''),period=String(fd.get('period')||'');if(!Number.isFinite(amount)||amount<=0||!workerId||!/^\d{4}-(0[1-9]|1[0-2])$/.test(period))throw new Error('Vérifiez l’employé, le montant et la période de paie.');await post('hr/quick-advance',{worker_id:workerId,amount,period,date:fd.get('date'),method:'cash',notes:'Acompte rapide depuis la caisse'});state.drawer=null;toast('Acompte enregistré dans le suivi de paie.','success');render();}else if(form.id==='customer-form'){const body=Object.fromEntries(fd.entries());body.price_tier=Number(body.price_tier)||1;await post('customers',body);state.drawer=null;toast('Client créé.','success');render();}else if(form.id==='zr-settings-form'){await window.electronAPI.zr.saveCredentials({tenantId:fd.get('tenantId'),apiKey:fd.get('apiKey')});toast('Identifiants ZR Express enregistrés de façon chiffrée.','success');render();}else if(form.id==='printer-form'){await window.electronAPI.printer.setDefault(fd.get('printer'));localStorage.setItem('samarinapos-label-printer',String(fd.get('label_printer')||''));localStorage.setItem('samarinapos-auto-print-receipt',form.elements.auto_print_receipt.checked?'true':'false');localStorage.setItem('samarinapos-auto-print-labels',form.elements.auto_print_labels.checked?'true':'false');toast('Imprimantes et options enregistrées.','success');}else if(form.id==='receipt-design-form'){const body=Object.fromEntries(fd.entries());for(const k of ['showLogo','showItems','showDiscount','showPayment','showQr','showWhatsapp'])body[k]=!!form.querySelector('[name='+k+']')?.checked;body.paperWidth=Number(body.paperWidth)||80;await window.electronAPI.printer.saveReceiptSettings(body);toast('Designer de ticket enregistré.','success');render();}else if(form.id==='general-settings-form'){const body=Object.fromEntries(fd.entries());if(form.dataset.logoData)body.store_logo=form.dataset.logoData;await put('settings/general',body);await post('settings/updateThemeSettings',{theme:body.theme});state.theme=body.theme;localStorage.setItem('sm-theme',state.theme);toast('Informations boutique et thème enregistrés.','success');render();}else if(form.id==='costing-form'){const body=Object.fromEntries(fd.entries());try{body.cipherMap=JSON.parse(body.cipherMap||'{}');}catch{throw new Error('Le chiffrement doit être un JSON valide.');}body.exchangeRate=Number(body.exchangeRate);body.markupPercent=Number(body.markupPercent);await put('posnic-next/settings/costing',body);toast('Règles EUR → DZD enregistrées.','success');render();}else if(form.id==='cost-preview'){const rate=Number(document.querySelector('[name=exchangeRate]')?.value)||280,markup=Number(document.querySelector('[name=markupPercent]')?.value)||0,rounding=document.querySelector('[name=rounding]')?.value||'none';let price=(Number(fd.get('eur'))||0)*rate+(Number(fd.get('extra'))||0);price*=1+markup/100;if(rounding==='50')price=Math.ceil(price/50)*50;if(rounding==='100')price=Math.ceil(price/100)*100;if(rounding==='x900')price=Math.floor(price/1000)*1000+900;if(rounding==='x950')price=Math.floor(price/1000)*1000+950;document.querySelector('#cost-preview-result').textContent=money(price)+' DZD';}else if(form.id==='zr-form'){const body=Object.fromEntries(fd.entries());const sale=await get('sales/'+body.saleId);const credentials=await window.electronAPI.zr.getCredentials();const parcel=await window.electronAPI.zr.createParcel(credentials,{customerName:body.customerName,phone:body.phone,cityTerritoryId:body.cityTerritoryId,districtTerritoryId:body.districtTerritoryId,address:body.address,deliveryType:body.deliveryType==='pickup-point'?'pickup-point':'home',sourceHubId:body.sourceHubId,deliveryFee:Number(body.deliveryFee)||0,codTotal:Number(body.codTotal)||0,description:body.description,items:(sale.items||[]).map(x=>({name:x.item_name||x.name,unitPrice:Number(x.item_price||x.unit_price||0),quantity:Number(x.item_quantity||x.quantity||1)}))});await post('delivery-zr/link',{saleId:body.saleId,parcel,recipientName:body.customerName,recipientPhone:body.phone,wilaya:body.cityTerritoryId,commune:body.districtTerritoryId,deliveryType:body.deliveryType,deliveryFee:Number(body.deliveryFee)||0,codTotal:Number(body.codTotal)||0,address:body.address});toast('Colis créé et lié au ticket POSNIC : '+parcel.trackingNumber,'success');render();}else if(form.id==='new-item-form'){const body=Object.fromEntries(fd.entries());for(const k of ['purchase_price_eur','purchase_exchange_rate','purchase_extra_dzd','company_price','selling_price','selling_price_2','selling_price_3','mrp_price','available_quantity','low_stock_alert','reorder_point','conversion_factor','tax','prep_minutes','position','n_kcal','n_protein_g','n_carbs_g','n_fat_g','n_sat_fat_g','n_fibre_g','n_sugar_g','n_sodium_mg'])body[k]=body[k]===''?0:Number(body[k])||0;for(const k of ['track_inventory','negative_stock','open_price','ecommerce','show_on_menu','item_weight_machine_based'])body[k]=!!form.querySelector('[name='+k+']')?.checked;for(const k of ['tags','barcodes','variant_options'])body[k]=String(body[k]||'').split(',').map(x=>x.trim()).filter(Boolean);const costing=await get('posnic-next/settings/costing').catch(()=>({exchangeRate:280}));body.purchase_exchange_rate=body.purchase_exchange_rate||Number(costing.exchangeRate)||280;body.purchase_base_dzd=Math.round(body.purchase_price_eur*body.purchase_exchange_rate*100)/100;const calc=body.purchase_base_dzd+Math.round(body.purchase_extra_dzd*100)/100;body.purchase_cost_dzd=calc;body.purchase_cost_manual_override=body.company_price>0&&Math.abs(body.company_price-calc)>.009;if(!body.purchase_cost_manual_override)body.company_price=calc;if(!body.barcode_id){let code='',unique=false;for(let i=0;i<20&&!unique;i++){code=String(1000000+crypto.getRandomValues(new Uint32Array(1))[0]%9000000);const found=rowsOf(await get('v2/items/fast-search',{q:code,limit:10,page:1}).catch(()=>[]));unique=!found.some(x=>String(x.barcode_id||'')===code);}if(!unique)throw new Error('Code-barres unique impossible à générer.');body.barcode_id=code;}if(body.name&&body.brand_abbreviation&&body.reference_date&&body.model_reference)body.name=(body.name+' '+body.brand_abbreviation+'-'+body.reference_date+'/'+body.model_reference).toLowerCase();if(body.image_url)body.image=body.image_url;const photoData=form.dataset.photoData||'';if(photoData){const comma=photoData.indexOf(','),raw=photoData.slice(comma+1),uploaded=await post('items/uploadItemMultiImage',{items_image:[{name:'samarinapos-item.jpg',size:Math.floor(raw.length*.75),cover:'yes',data:raw}]});const first=rowsOf(uploaded)[0]||uploaded?.[0];if(first?.name){body.image=first.name;body.image_url=first.name;body.images=[first];}}let created;if(body.variants_enabled==='on'){const rows=[...form.querySelectorAll('[data-variant-row]')];if(!rows.length)throw new Error('Générez au moins une variante.');const items=rows.map(row=>({ ...body,name:[body.name,row.querySelector('[name=variant_label]').value.trim()].filter(Boolean).join(' · '),barcode_id:row.querySelector('[name=variant_barcode]').value.trim(),available_quantity:Number(row.querySelector('[name=variant_stock]').value)||0,variant_value:row.querySelector('[name=variant_label]').value.trim(),variant_axis:body.variant_axis}));body.variant_axis=form.dataset.variantAxis||body.variant_axis;delete body.variant_axis_2;delete body.variant_values_2;created=await post('items/createFamily',{variant_axis:body.variant_axis,variant_parent_name:body.name,items});state.newlyCreatedItem={...body,...items[0]};}else{delete body.variants_enabled;delete body.variant_axis;delete body.variant_values;created=await post('items',body);state.newlyCreatedItem={...body,...(created?.data||created||{})};}state.labelQueue=[state.newlyCreatedItem];state.drawer={title:'Article créé avec succès',html:'<div class="panel"><h3>Votre article est enregistré.</h3><p>Imprimez immédiatement son étiquette de prix ou créez un autre article.</p><div class="actions"><button class="btn primary" data-action="print-new-item-label">Imprimer les étiquettes</button><button class="btn" data-action="create-another-item">Créer un autre article</button></div></div>'};toast('Article créé.','success');render();}else if(form.id==='item-form'){const body=Object.fromEntries(fd.entries());for(const key of ['company_price','selling_price','selling_price_2','selling_price_3','available_quantity'])body[key]=Number(body[key])||0;const original=await get('items/'+form.dataset.id);delete original._id;if(body.image_url)body.image=body.image_url;await put('items/'+form.dataset.id,{...original,...body});state.drawer=null;toast('Article mis à jour.','success');render();}else if(form.id==='receiving-form'){const body=Object.fromEntries(fd.entries()),supplier=form.querySelector('[name=supplier_id] option:checked');body.supplier_name=supplier?.dataset.name||supplier?.textContent||'';body.supplier_address=supplier?.dataset.address||'';body.supplier_phone=supplier?.dataset.phone||'';body.items=[...form.querySelectorAll('[data-purchase-row]')].map(row=>{const item=row.querySelector('[name=item_id]'),quantity=Number(row.querySelector('[name=item_quantity]').value)||0,eur=Number(row.querySelector('[name=purchase_price_eur]').value)||0,rate=Number(row.querySelector('[name=exchange_rate]').value)||0,extra=Number(row.querySelector('[name=extra_dzd]').value)||0;return {item_id:item.value,item_name:item.selectedOptions[0]?.dataset.name||'',item_quantity:quantity,item_unit:'qty',purchase_price_eur:eur,purchase_exchange_rate:rate,purchase_extra_dzd:extra,purchase_cost_dzd:Math.round(eur*rate*100)/100+Math.round(extra*100)/100};}).filter(x=>x.item_id&&x.item_quantity>0);if(!body.items.length)throw new Error('Ajoutez au moins un article et une quantité valide.');await post('receivings',body);state.labelQueue=body.items.map(x=>({name:x.item_name,company_price:x.purchase_cost_dzd}));state.drawer={title:'Réception enregistrée',html:'<div class="panel"><h3>Le stock a été mis à jour.</h3><button class="btn primary" data-action="print-receiving-labels">Imprimer les étiquettes du bon</button></div>'};toast('Réception créée.','success');render();}else if(form.id==='zr-form'){await post('delivery-zr/customer',Object.fromEntries(fd.entries()));toast('Client ZR Express créé / vérifié.','success');render();}else if(form.id==='settle-form'){await post('credit/settle/'+encodeURIComponent(form.dataset.customerId),{amount:Number(fd.get('amount')),payment_mode:fd.get('method'),method:fd.get('method')});state.drawer=null;toast('Versement enregistré.','success');render();}else if(form.id==='discount-form'){const discount=Math.max(0,Number(fd.get('discount'))||0);basket().discount=discount;state.drawer=null;toast('Remise enregistrée sur le panier.','success');render();}else if(form.id==='theme-form'){await post('settings/updateThemeSettings',{theme:fd.get('theme')});toast('Thème enregistré.','success');}else if(form.id==='pin-form'){await window.electronAPI?.lock?.enroll?.({username:fd.get('username'),pin:fd.get('pin')});state.drawer=null;toast('PIN utilisateur configuré.','success');render();}else if(form.id==='whatsapp-config-form'){const phone=String(fd.get('owner_phone')||'').trim();localStorage.setItem('samarinapos-owner-whatsapp',phone);localStorage.setItem('samarinapos-auto-z-report',form.elements.auto_z_report.checked?'true':'false');await post('settings/saveWhatsAppReceipt',{whatsapp_receipt:form.elements.whatsapp_receipt.checked});toast('Préférences WhatsApp enregistrées.','success');render();}else if(form.id==='whatsapp-template-form'){await post('whatsapp/saveTemplate',{name:'Rappel de dette',message:fd.get('message'),template_type:'debt_reminder'});toast('Modèle de relance enregistré.','success');}else if(form.id==='whatsapp-send'){await post('whatsapp/sendMessage',{phone_number:fd.get('phone'),message:fd.get('message')});toast('Message WhatsApp envoyé.','success');}}catch(err){toast(err.message,'error');}});
async function boot(){const ok=await checkSession();if(ok){state.view=location.hash.slice(1)||'caisse';startMobileBasketSync();await render();}else login();}
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(modules.some(x=>x.id===id)){state.view=id;state.tab=0;render();}});
boot();
